// Real records are kept separate from every synthetic demo object and renderer.
const realNav=[['overview','Рабочий стол'],['strategies','Стратегии'],['backtests','Бэктесты'],['trades','Реальная торговля'],['accounts','Счета'],['comparison','Сравнение'],['logs','Логи']];
icons.trades=icons.logs;icons.accounts=icons.monitor;
for(const [key,label] of realNav)if(!navs.some(n=>n[0]===key))navs.push([key,label]);
let dataMode=localStorage.getItem('atlas-source')||'real';
let remote=null,remoteBusy=false,remoteError='';
let rf={account:'all',strategy:'all',symbol:'all',currency:'USD',start:'',end:'',page:0,run:'',compareStrategy:'',compareAccount:'',compareSymbol:'',compareRun:'',compareStart:'',compareEnd:'',comparePage:0};
try{const saved=JSON.parse(localStorage.getItem('atlas-comparison-v1'));for(const k of ['compareRun','compareStrategy','compareAccount','compareSymbol','compareStart','compareEnd'])if(typeof saved?.[k]==='string')rf[k]=saved[k]}catch{}
const n=v=>Number.isFinite(Number(v))?Number(v):0;
const sum=(rows,fn)=>rows.reduce((a,r)=>a+fn(r),0);
const net=d=>n(d.profit)+n(d.commission)+n(d.swap)+n(d.fee);
const money=(v,c=rf.currency)=>new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v)+' '+esc(c);
const shortMoney=(v,c=rf.currency)=>new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:2}).format(v)+' '+esc(c);
const stamp=v=>v?new Date(v).toLocaleString('ru-RU',{timeZone:'UTC',hour12:false})+' UTC':'Нет данных';
const akey=a=>a.server+'|'+a.login;
const dkey=d=>d.server+'|'+d.login+'|'+d.ticket;
const accountFor=d=>remote.accounts.find(a=>a.server===d.server&&a.login===d.login);
const unassigned=s=>!s||s==='unmapped';
const sname=s=>unassigned(s)?'Без привязки · unmapped':s;
const includedDeal=d=>!d._excluded_ea;
const color=v=>v<0?'down':v>0?'up':'muted';
const filterValues=v=>v==='all'?null:Array.isArray(v)?v:[v];
const filterMatches=(selection,value)=>selection==='all'||filterValues(selection).includes(value);
function selectedAccounts(){return remote.accounts.filter(a=>a.currency===rf.currency&&filterMatches(rf.account,akey(a)))}
function selectedDeals({dates=true,strategy=true,symbol=true,tradeOnly=true,includeExcluded=false}={}){const keys=new Set(selectedAccounts().map(akey));return remote.deals.filter(d=>(includeExcluded||includedDeal(d))&&keys.has(akey(d))&&(!tradeOnly||d.kind==='trade')&&(!strategy||filterMatches(rf.strategy,d.strategy||'unmapped'))&&(!symbol||filterMatches(rf.symbol,d.symbol))&&(!dates||(!rf.start||d.time_utc.slice(0,10)>=rf.start)&&(!rf.end||d.time_utc.slice(0,10)<=rf.end)))}
function groups(rows){const m=new Map();for(const d of rows){const key=d.strategy||'unmapped';if(!m.has(key))m.set(key,[]);m.get(key).push(d)}return [...m].map(([name,deals])=>({name,deals,pnl:sum(deals,net),symbols:[...new Set(deals.map(d=>d.symbol))],accounts:new Set(deals.map(akey)).size,exits:deals.filter(d=>[1,2,3].includes(d.entry)).length})).sort((a,b)=>unassigned(a.name)-unassigned(b.name)||a.name.localeCompare(b.name))}
function daySeries(rows,dateFn,valueFn){const m=new Map();for(const row of rows){const day=dateFn(row);m.set(day,(m.get(day)||0)+valueFn(row))}return [...m].sort((a,b)=>a[0].localeCompare(b[0])).map(([day,value])=>({day,value}))}
function cumul(rows){let amount=0;return rows.map(r=>({day:r.day,value:amount+=r.value}))}
function actualChart(series,{labels=['Net PnL'],currency=rf.currency}={}){
 if(!series.some(s=>s.length))return '<div class="real-empty">Нет данных для графика в выбранном периоде.</div>';
 const all=series.flat(),dates=all.map(p=>p.day).sort(),start=Date.parse(dates[0]),end=Date.parse(dates.at(-1));
 let lo=Math.min(0,...all.map(p=>p.value)),hi=Math.max(0,...all.map(p=>p.value));if(hi===lo)hi=lo+1;
 const range=hi-lo;lo-=range*.08;hi+=range*.08;const x=d=>48+(Date.parse(d)-start)/(end-start||1)*650,y=v=>220-(v-lo)/(hi-lo)*185;
 const colours=['#4869e8','#5a9b83'];
 return `<svg class="real-chart" viewBox="0 0 760 268" role="img" aria-label="${esc(labels.join(' / '))} · ${esc(currency)}">${[0,1,2,3,4].map(i=>{let v=lo+(hi-lo)*i/4;return `<line x1="48" x2="700" y1="${y(v)}" y2="${y(v)}" stroke="#e9edf2" stroke-dasharray="3 4"/><text x="708" y="${y(v)+4}">${new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(v)}</text>`}).join('')}<line x1="48" x2="700" y1="${y(0)}" y2="${y(0)}" stroke="#c8d0da"/>${series.map((s,i)=>s.length?`<path d="${s.map((p,j)=>(j?'L':'M')+x(p.day).toFixed(2)+','+y(p.value).toFixed(2)).join(' ')}" fill="none" stroke="${colours[i]}" stroke-width="2.4"/><circle cx="${x(s.at(-1).day)}" cy="${y(s.at(-1).value)}" r="3.5" fill="${colours[i]}"/>`:'').join('')}<text x="48" y="250">${dates[0]}</text><text x="700" y="250" text-anchor="end">${dates.at(-1)}</text></svg>`
}
function empty(title,text){return `<div class="real-empty"><h2>${title}</h2>${text}</div>`}
function filterOptions(field){
 const accounts=remote.accounts.filter(a=>a.currency===rf.currency);
 if(field==='account')return accounts.map(a=>[akey(a),a.login+' · '+a.server]);
 const keys=new Set(accounts.map(akey)),rows=remote.deals.filter(d=>d.kind==='trade'&&includedDeal(d)&&keys.has(akey(d)));
 return [...new Set(rows.map(d=>field==='strategy'?d.strategy||'unmapped':d.symbol).filter(Boolean))].sort().map(v=>[v,field==='strategy'?sname(v):v]);
}
function multiFilter(field,label,allLabel,config={}){
 const options=config.options||filterOptions(field),selection=config.selection??rf[field],values=filterValues(selection),scope=config.scope||'history';
 const caption=values===null?allLabel:!values.length?'Ничего не выбрано':values.length===1?(options.find(o=>o[0]===values[0])?.[1]||values[0]):'Выбрано: '+values.length;
 return `<div class="multi-field"><span id="r-${field}-label" class="filter-label">${label}</span><details class="multi-filter" data-multi="${field}" data-multi-scope="${scope}"><summary id="r-${field}" aria-labelledby="r-${field}-label r-${field}-value"><span id="r-${field}-value" title="${esc(caption)}">${esc(caption)}</span><b>⌄</b></summary><div class="multi-popover"><input type="search" data-multi-search aria-label="Поиск: ${label}" placeholder="Найти…"><div class="multi-tools"><button type="button" data-multi-action="all">Выбрать все</button><button type="button" data-multi-action="none">Снять все</button></div><div class="multi-options" role="group" aria-label="${label}">${options.map(([v,l])=>`<label class="multi-option"><input type="checkbox" value="${esc(v)}" ${filterMatches(selection,v)?'checked':''}><span>${esc(l)}</span></label>`).join('')}</div><p class="multi-no-results" hidden>Совпадений нет</p><div class="multi-footer"><span data-multi-count>Отмечено: ${values===null?options.length:values.length}</span><button type="button" class="btn primary" data-multi-action="apply">Применить</button></div></div></details></div>`;
}
function realFilters(){
 const active=rf.account!=='all'||rf.strategy!=='all'||rf.symbol!=='all'||rf.start||rf.end;
 const parts=[['account','Счета'],['strategy','Стратегии'],['symbol','Инструменты']].filter(([k])=>rf[k]!=='all').map(([k,l])=>l+': '+filterValues(rf[k]).length);
 if(rf.start||rf.end)parts.push((rf.start||'Начало истории')+' → '+(rf.end||'Последняя запись'));
 return (state.page==='overview'?'':exclusionNotice())+`<details class="filter-disclosure" ${active||state.page==='trades'?'open':''}><summary>${icon('filter')}<strong>Фильтры</strong><span>${active?esc(parts.join(' · ')):'Все счета · все стратегии · вся история'} · ${esc(rf.currency)}</span><b>Настроить</b></summary><div class="real-filters">${multiFilter('account','Счета · '+esc(rf.currency),'Все счета')}${multiFilter('strategy','Стратегии · VPS / локально','Все стратегии')}${multiFilter('symbol','Инструменты','Все инструменты')}<div><label for="r-start">С даты · UTC</label><input id="r-start" data-real-filter="start" type="date" value="${rf.start}"></div><div><label for="r-end">По дату · UTC</label><input id="r-end" data-real-filter="end" type="date" value="${rf.end}"></div>${button('Сбросить','real-reset')}</div><p class="filter-help">Можно выбрать несколько значений. Разные фильтры применяются вместе; изменения списка — по кнопке «Применить».</p>${rf.start&&rf.end&&rf.start>rf.end?'<div class="notice">Начало периода позже конца — измените даты.</div>':''}</details>`;
}
function multiCount(menu){menu.querySelector('[data-multi-count]').textContent='Отмечено: '+menu.querySelectorAll('input[type="checkbox"]:checked').length}
document.addEventListener('click',e=>{
 const control=e.target.closest('[data-multi-action]');
 if(control){
  const menu=control.closest('[data-multi]'),op=control.dataset.multiAction;
  if(op==='apply'){const inputs=[...menu.querySelectorAll('input[type="checkbox"]')],chosen=inputs.filter(x=>x.checked).map(x=>x.value),field=menu.dataset.multi;if(menu.dataset.multiScope==='logs'){logsCaptureDraft();logsSelection[field]=chosen.length===inputs.length?'all':chosen;logsSelection.page=0;logsSelection.legacy_terminal='';return fetchLogs()}rf[field]=chosen.length===inputs.length?'all':chosen;rf.page=0;render();document.getElementById('r-'+field)?.focus();return}
  menu.querySelectorAll('input[type="checkbox"]').forEach(x=>x.checked=op==='all');multiCount(menu);return;
 }
 document.querySelectorAll('.multi-filter[open]').forEach(menu=>{if(!menu.contains(e.target))menu.open=false});
});
document.addEventListener('change',e=>{const menu=e.target.closest('.multi-filter');if(menu&&e.target.type==='checkbox')multiCount(menu)});
document.addEventListener('input',e=>{if(!e.target.hasAttribute('data-multi-search'))return;const menu=e.target.closest('.multi-filter'),q=e.target.value.trim().toLocaleLowerCase();let visible=0;menu.querySelectorAll('.multi-option').forEach(row=>{row.hidden=!row.textContent.toLocaleLowerCase().includes(q);if(!row.hidden)visible++});menu.querySelector('.multi-no-results').hidden=visible>0});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const menu=e.target.closest('.multi-filter');if(menu){menu.open=false;menu.querySelector('summary').focus()}}});
function sourceStrip(){if(state.page==='logs'&&typeof logsSourceStrip==='function')return logsSourceStrip();return `<div class="source-strip ${remoteError?'error':''}"><div><strong>${remoteError?'Не удалось обновить снимок':'Снимок VPS'}</strong><span>${remote?stamp(remote.fetched_at):'Загрузка данных…'}</span>${remoteError?'<span>'+esc(remoteError)+'</span>':''}</div><button class="btn" data-action="real-refresh" ${remoteBusy?'disabled':''}>${icon('refresh')}${remoteBusy?'Загрузка…':'Обновить'}</button></div>`}
function exclusionNotice(){
 const rows=selectedDeals({includeExcluded:true}),excluded=rows.filter(d=>!includedDeal(d));
 return `<section class="exclusion-notice"><div><strong>Статистика без внешних EA</strong><p>QQ, Gold Reaper, GolgGrid · исключено ${excluded.length} записей в текущей выборке. Неопределённые записи пока учитываются.</p></div>${button('Исключения','real-exclusions')}</section>`;
}
let exclusionPage=0;
function showExclusions(){
 const all=selectedDeals({includeExcluded:true}),rows=all.filter(d=>!includedDeal(d)),included=all.filter(includedDeal),names=['QQ','Gold Reaper','GolgGrid'];
 const pages=Math.max(1,Math.ceil(rows.length/30));exclusionPage=Math.min(exclusionPage,pages-1);
 overlay(`<div class="eyebrow">ЛОКАЛЬНЫЕ ИСКЛЮЧЕНИЯ</div><h1>Что входит в PnL</h1><p class="subtitle">Текущие счета, стратегии, инструменты и даты. Валюта: ${esc(rf.currency)}.</p><div class="cards">${card('Вся выборка до исключений',money(sum(all,net)),all.length+' записей')}${card('Исключено',money(sum(rows,net)),rows.length+' записей')}${card('Учтено в статистике',money(sum(included,net)),included.length+' записей')}</div><div class="table-scroll"><table class="table"><thead><tr><th>EA</th><th>ЗАПИСИ</th><th>ИСКЛЮЧЁННЫЙ NET PNL</th></tr></thead><tbody>${names.map(name=>{const r=rows.filter(d=>d._excluded_ea.name===name);return `<tr><td>${name}</td><td>${r.length||'Не найдено'}</td><td>${r.length?money(sum(r,net)):'—'}</td></tr>`}).join('')}</tbody></table></div><p class="real-caption">На счёте 53015232 (vps-254) группа QQ / magic 1234 исключается. ${remote.deals.some(d=>d._excluded_ea?.name==='GolgGrid')?'Отдельная подпись GolgGrid обнаружена и исключена.':'Отдельная подпись GolgGrid в текущем снимке не найдена.'} Собственные S-009 и S-019 на этом счёте сохраняются. Балансы счетов не пересчитываются.</p><p class="real-caption">Неопределённые записи вне этих EA остаются в статистике. Сброс фильтров и отключение локальных привязок не отменяют исключения. Оригинальные суммы и сделки сохранены.</p><h2>Исключённые записи</h2><div class="table-scroll"><table class="table"><thead><tr><th>EA / СЧЁТ</th><th>СДЕЛКА / MAGIC</th><th>NET PNL</th></tr></thead><tbody>${rows.slice(exclusionPage*30,(exclusionPage+1)*30).map(d=>`<tr><td>${esc(d._excluded_ea.name)}<small>${esc(d.login+' · '+d.server)}</small></td><td><button class="real-link" data-action="real-deal:${encodeURIComponent(dkey(d))}">#${esc(d.ticket)} ↗</button><small>${esc(d.symbol)} · magic ${esc(d.magic)}</small></td><td>${money(net(d))}</td></tr>`).join('')||'<tr><td colspan="3">В этой выборке нет исключённых записей.</td></tr>'}</tbody></table></div><div class="real-pagination"><span>${exclusionPage+1} / ${pages}</span><div class="row">${exclusionPage?button('← Назад','real-exclusions-prev'):''}${exclusionPage+1<pages?button('Далее →','real-exclusions-next'):''}</div></div>${button('Закрыть','close',true)}`,true);
 document.querySelector('.drawer')?.setAttribute('aria-label','Исключения из статистики');
}
function pnlPanel(rows,title='Накопленный PnL торговых сделок'){const daily=daySeries(rows,d=>d.time_utc.slice(0,10),net);return `<section class="panel"><div class="panelhead"><div><h2>${title}</h2><p>Торговые записи · расходы учтены · UTC · ${esc(rf.currency)}</p></div></div><div class="chartwrap">${actualChart([cumul(daily)])}</div><p class="real-caption">Profit + commission + swap + fee. Вводы, выводы и прочие операции исключены. Это накопленный результат сделок, а не историческая equity.</p></section>`}
function groupTable(list){return `<div class="table-scroll"><table class="table real-table"><thead><tr><th>СТРАТЕГИЯ</th><th>ИНСТРУМЕНТЫ</th><th>NET PNL</th><th>ЗАПИСИ / ВЫХОДЫ</th><th>СЧЕТА</th></tr></thead><tbody>${list.map(g=>`<tr><td class="real-name"><button class="real-link" data-action="real-strategy:${encodeURIComponent(g.name)}">${esc(sname(g.name))} ↗</button></td><td class="real-name">${esc(g.symbols.join(', '))}</td><td class="num ${color(g.pnl)}">${money(g.pnl)}</td><td>${g.deals.length} / ${g.exits}</td><td>${g.accounts}</td></tr>`).join('')||'<tr><td colspan="5">Нет записей для выбранных фильтров.</td></tr>'}</tbody></table></div>`}
function workspaceFlow(){return `<section class="workspace-route" aria-label="Путь стратегии">${[
 ['01','strategies','Стратегии','Библиотека и история'],['02','backtests','Бэктесты',remote.backtests.length+' сохранённых отчётов'],['03','trades','Реальная торговля','Сделки и расходы'],['04','comparison','Сравнение','Бэктест и исполнение']
].map(([num,id,title,desc])=>`<button data-action="${id}"><span class="route-number">${num}</span><strong>${title}</strong><small>${desc}</small>${icon('chevron')}</button>`).join('')}</section>`}
function realOverview(){const rows=selectedDeals(),list=groups(rows),accounts=selectedAccounts();return heading('ATLAS / WORKSPACE','Рабочий стол','Стратегии, исследования и торговля в одном пространстве.',button('Открыть стратегии','strategies',true,'arrow'))+
 workspaceFlow()+exclusionNotice()+realFilters()+`<div class="cards overview-metrics">${card('Net PnL · без внешних EA',shortMoney(sum(rows,net)),money(sum(rows,net)))}${card('Записи исполнения',fmt(rows.length),rows.filter(d=>[1,2,3].includes(d.entry)).length+' выходов / частичных выходов')}${card('Группы стратегий',list.filter(g=>!unassigned(g.name)).length,'Отдельно по инструменту и подписи')}${card('Счета в выборке',accounts.length,esc(rf.currency)+' · по сохранённым снимкам')}</div>
 <div class="real-split overview-performance">${pnlPanel(rows,'Результат торговли')}<section class="panel workspace-context"><div class="panelhead"><h2>Быстрый доступ</h2></div><div class="context-body"><div class="context-item"><span class="context-icon">${icon('backtests')}</span><div><strong>${remote.backtests.length} бэктестов</strong><p>Импортированные дневные результаты</p></div>${button('Открыть','backtests')}</div><div class="context-item"><span class="context-icon">${icon('accounts')}</span><div><strong>${remote.positions.filter(p=>accounts.some(a=>akey(a)===akey(p))).length} открытых позиций</strong><p>Состояние на момент снимков счетов</p></div>${button('Счета','accounts')}</div><div class="context-foot"><span>Привязка сделок</span><b>Разбор приостановлен</b><p>Принятые привязки сохранены. Внешние EA исключены; остальные неопределённые записи пока учитываются.</p>${button('Данные и привязки','mapping')}</div></div></section></div>
 <section class="panel"><div class="panelhead"><div><h2>Результаты по стратегиям</h2><p>Выбранный период · ${esc(rf.currency)}</p></div>${button('Библиотека','strategies',false,'arrow')}</div>${groupTable(list)}</section>`}

function realStrategies(){const rows=selectedDeals(),list=groups(rows);return heading('ИССЛЕДОВАНИЯ / БИБЛИОТЕКА','Ваши стратегии','Группы по инструментам и исходным подписям. Откройте историю нужной стратегии.',button('Создать · демо','mode-demo',false,'plus'))+realFilters()+`<div class="library-summary"><span><b>${list.filter(g=>!unassigned(g.name)).length}</b> подписанных групп</span><span><b>${remote.backtests.length}</b> бэктестов в библиотеке</span><span>История исполнения · ${esc(rf.currency)}</span></div><div class="strategy-grid">${list.map(g=>{const family=(g.name.match(/^S-\d{3}/)||[])[0];const local=g.deals.some(d=>d._local_mapping);return `<article class="panel strategy-tile"><div class="tile-heading"><span class="strategy-monogram">${family?family.slice(2):'—'}</span><div><h2>${esc(family?(local?family+' · '+g.name.split(' · ')[1]:family):'Без привязки')}</h2><p>${esc(g.symbols.join(' · '))}</p></div><span class="badge ${unassigned(g.name)?'gray':'blue'}">${local?'Локальная привязка':unassigned(g.name)?'Отдельная группа':'Подпись VPS'}</span></div><p class="strategy-version">${esc(local?'Версия не установлена':g.name)}</p><div class="tile-chart">${actualChart([cumul(daySeries(g.deals,d=>d.time_utc.slice(0,10),net))])}</div><div class="tile-period"><span>${esc(g.deals[0].time_utc.slice(0,10))}</span><span>${esc(g.deals.at(-1).time_utc.slice(0,10))}</span></div><div class="strategy-stats"><div><small>Net PnL · ${esc(rf.currency)}</small><b class="${color(g.pnl)}">${shortMoney(g.pnl,'')}</b></div><div><small>Записей</small><b>${g.deals.length}</b></div><div><small>Счетов</small><b>${g.accounts}</b></div></div><div class="tile-bottom"><span>По истории сделок</span>${button('Сделки','real-strategy:'+encodeURIComponent(g.name),false,'arrow')}</div></article>`}).join('')}</div>${!list.length?empty('Нет записей','Измените фильтры.'):''}<details class="data-explainer"><summary>Как читать библиотеку стратегий</summary><p>Локальные привязки определяют семейство и инструмент. Версия кода и выделенный капитал не подтверждены. Группы с исходными подписями VPS сохранены отдельно; наличие сделок в истории не означает, что советник сейчас работает.</p></details>`}

function tradeAccountSelected(key){const values=filterValues(rf.account);return values?.length===1&&values[0]===key}
function tradeAccountToggle(d){const active=tradeAccountSelected(akey(d));return `<button type="button" class="trade-account-toggle ${active?'active':''}" data-action="real-trade-account:${encodeURIComponent(akey(d))}" aria-pressed="${active}" title="${active?'Показать все счета':'Показать сделки этого счёта'}" aria-label="${active?'Все счета вместо':'Фильтровать по счёту'} ${esc(d.login+' · '+d.server)}"><span>${esc(d.login)}</span><span aria-hidden="true">${active?'×':'⇄'}</span></button><span class="trade-account-server">${esc(d.server)}</span>`}
function toggleTradeAccount(key){rf.account=tradeAccountSelected(key)?'all':[key];rf.page=0}
function realTrades(){const rows=selectedDeals().slice().reverse(),limit=50,pages=Math.max(1,Math.ceil(rows.length/limit));rf.page=Math.min(rf.page,pages-1);const shown=rows.slice(rf.page*limit,(rf.page+1)*limit);return heading('ИСПОЛНЕНИЕ / ЖУРНАЛ','Реальная торговля','Это записи MT5 deals, включая входы и частичные выходы. Их число не равно числу закрытых позиций.',button('Экспорт выборки','real-csv',false,'download'))+realFilters()+`<div class="real-meta"><span>${rows.length} записей</span><span>Net PnL ${money(sum(rows,net))}</span><span>Расходы ${money(sum(rows,d=>n(d.commission)+n(d.swap)+n(d.fee)))}</span><span>UTC</span></div><section class="panel"><div class="table-scroll"><table class="table real-table"><thead><tr><th>ВРЕМЯ / TICKET</th><th>СТРАТЕГИЯ / СЧЁТ</th><th>СИМВОЛ</th><th>СДЕЛКА</th><th>LOT</th><th>PROFIT</th><th>РАСХОДЫ</th><th>NET PNL</th></tr></thead><tbody>${shown.map(d=>`<tr><td><button class="real-link" data-action="real-deal:${encodeURIComponent(dkey(d))}">${esc(d.time_utc.slice(0,19).replace('T',' '))} ↗</button><small>#${esc(d.ticket)}</small></td><td class="real-name">${esc(sname(d.strategy))}<small>${tradeAccountToggle(d)}</small></td><td>${esc(d.symbol)}</td><td>${d.type===0?'Buy':d.type===1?'Sell':'Type '+d.type}<small>${['Вход','Выход','Разворот','Close by'][d.entry]||'Неизвестно'}</small></td><td>${d.volume}</td><td class="num">${money(n(d.profit),'')}</td><td class="num">${money(n(d.commission)+n(d.swap)+n(d.fee),'')}</td><td class="num ${color(net(d))}">${money(net(d),'')}</td></tr>`).join('')||'<tr><td colspan="8">Нет записей для выбранных фильтров.</td></tr>'}</tbody></table></div><div class="real-pagination"><span class="updated">Страница ${rf.page+1} / ${pages} · ${rf.currency}</span><div class="row">${rf.page?button('← Назад','real-prev'):''}${rf.page+1<pages?button('Далее →','real-next'):''}</div></div></section>`}
function realDeal(key){const d=remote.deals.find(d=>dkey(d)===key);if(!d)return;const c=accountFor(d)?.currency||'';overlay(`<div class="eyebrow" style="margin-top:15px">VPS / MT5 DEAL</div><h1>Сделка #${esc(d.ticket)}</h1><p class="subtitle">${esc(sname(d.strategy))} · ${esc(d.symbol)} · ${stamp(d.time_utc)}</p><div class="cards">${card('Profit',money(n(d.profit),c),'Из записи VPS')}${card('Расходы',money(n(d.commission)+n(d.swap)+n(d.fee),c),'Commission + swap + fee')}${card('Net PnL',money(net(d),c),'Сумма четырёх полей')}</div>${[['Счёт',d.login+' · '+d.server],['Position ID',d.position_id],['Magic',d.magic],['Исполнение',(d.type===0?'Buy':'Sell')+' · '+(['Вход','Выход','Разворот','Close by'][d.entry]||d.entry)],['Объём',d.volume+' lot'],['Локальный день отчёта',d.day_local]].map(([k,v])=>`<div class="config-row"><span>${k}</span><b>${esc(v)}</b></div>`).join('')}<h2 style="margin-top:24px">Комментарий сделки</h2><div class="rawcomment">${esc(d.comment||'Отсутствует')}</div><div class="notice">Исторические цены входа/выхода и сигнал стратегии в этой таблице не сохранены. Проскальзывание и причины исполнения здесь не вычисляются.</div>${button('Закрыть','close',true)}`,true)}
function realAccounts(){const accounts=selectedAccounts();return heading('ДАННЫЕ / СЧЕТА','Счета и позиции','Баланс и позиции — исходные данные всего счёта, включая внешние EA. Это не результат отобранных стратегий; время снимков может различаться.')+`<div class="cards">${card('Счетов',accounts.length,'Валюта '+esc(rf.currency))}${card('Баланс счетов · все EA',shortMoney(sum(accounts,a=>n(a.balance))),money(sum(accounts,a=>n(a.balance))))}${card('Открытых позиций',remote.positions.filter(p=>accounts.some(a=>akey(a)===akey(p))).length,'По последним снимкам')}${card('Хостов',remote.hosts.length,'Сборщики на VPS')}</div><section class="panel"><div class="table-scroll"><table class="table real-table"><thead><tr><th>СЧЁТ / СЕРВЕР</th><th>БАЛАНС</th><th>ПОЗИЦИИ / FLOATING</th><th>ПОСЛЕДНИЙ СНИМОК</th><th>АКТУАЛЬНОСТЬ</th></tr></thead><tbody>${accounts.map(a=>{let ps=remote.positions.filter(p=>akey(p)===akey(a));let ts=remote.terminal_status.find(t=>t.host_id===a.host_id&&t.terminal_id===a.terminal_id);let age=(Date.now()-Date.parse(a.latest_snapshot_utc))/1000;let fresh=age>=0&&age<=750&&ts?.received_utc===a.latest_snapshot_utc&&ts?.data_complete==='true';return `<tr><td><button class="real-link" data-action="real-account:${encodeURIComponent(akey(a))}">${esc(a.login)} ↗</button><small>${esc(a.server)}</small></td><td class="num">${money(n(a.balance),a.currency)}</td><td>${ps.length} / ${money(sum(ps,p=>n(p.profit)+n(p.swap)),a.currency)}</td><td>${stamp(a.latest_snapshot_utc)}</td><td><span class="badge ${fresh?'':'warn'}">${fresh?'Свежий':'Устарел / неполный'}</span></td></tr>`}).join('')}</tbody></table></div></section><section class="panel" style="margin-top:20px"><div class="panelhead"><h2>Открытые позиции</h2></div><div class="table-scroll"><table class="table real-table"><thead><tr><th>СТРАТЕГИЯ / СЧЁТ</th><th>ИНСТРУМЕНТ</th><th>ОБЪЁМ</th><th>ВХОД / ТЕКУЩАЯ</th><th>FLOATING + SWAP</th></tr></thead><tbody>${remote.positions.filter(p=>accounts.some(a=>akey(a)===akey(p))).map(p=>`<tr><td>${esc(sname(p.strategy))}<small>${esc(p.login)}</small></td><td>${esc(p.symbol)} · ${p.type===0?'Buy':'Sell'}</td><td>${p.volume}</td><td>${p.price_open} / ${p.price_current}</td><td>${money(n(p.profit)+n(p.swap))}</td></tr>`).join('')||'<tr><td colspan="5">Нет открытых позиций в снимке.</td></tr>'}</tbody></table></div></section>`}
function runDays(run){return remote.backtest_days.filter(d=>d.run_id===run.run_id).map(d=>({day:d.day,value:n(d.net_pnl)}))}
function runStats(run){const rows=runDays(run);let balance=n(run.starting_capital),peak=balance,dd=0,ddMoney=0;for(const r of rows){balance+=r.value;peak=Math.max(peak,balance);ddMoney=Math.max(ddMoney,peak-balance);if(peak>0)dd=Math.max(dd,(peak-balance)/peak*100)}return {pnl:sum(rows,r=>r.value),ret:(balance/n(run.starting_capital)-1)*100,dd,ddMoney,rows}}
function realBacktests(){if(!remote.backtests.length)return empty('Бэктесты ещё не импортированы','В базе VPS нет сохранённых прогонов.');const run=remote.backtests.find(r=>r.run_id===rf.run)||remote.backtests[0];rf.run=run.run_id;const m=runStats(run);return heading('ИССЛЕДОВАНИЯ / БЭКТЕСТЫ','Библиотека бэктестов','Исходные отчёты из Backtest Lab. Расчёты ниже основаны на сохранённом дневном Net PnL.')+`<div class="real-run-layout"><div class="real-run-picker"><label for="run-picker">Выберите бэктест · ${remote.backtests.length} отчётов</label><select id="run-picker">${remote.backtests.map(r=>`<option value="${esc(r.run_id)}" ${r.run_id===run.run_id?'selected':''}>${esc(r.strategy)} · ${r.first_day} — ${r.last_day}</option>`).join('')}</select></div><aside class="real-run-list">${remote.backtests.map(r=>`<button class="real-run-button ${r.run_id===run.run_id?'active':''}" data-action="real-run:${encodeURIComponent(r.run_id)}"><strong>${esc(r.strategy)}</strong><small>${r.first_day} → ${r.last_day}</small><small>${r.row_count} исходных строк · ${esc(r.currency)}</small></button>`).join('')}</aside><div><div class="panelhead" style="padding:0 0 20px"><div><h2>${esc(run.strategy)}</h2><p>${esc(run.file_name)}</p></div><span class="badge blue">Импорт VPS</span></div><div class="cards">${card('Net PnL',shortMoney(m.pnl,run.currency),money(m.pnl,run.currency))}${card('Доходность',(m.ret>=0?'+':'')+m.ret.toFixed(2)+'%', 'Капитал '+money(n(run.starting_capital),run.currency))}${card('Max DD дневного баланса',m.dd.toFixed(2)+'%','Не intraday equity drawdown')}${card('Дней с записью',m.rows.length,run.row_count+' исходных строк отчёта')}</div><section class="panel"><div class="panelhead"><h2>Накопленный результат бэктеста</h2><span class="updated">${esc(run.currency)}</span></div><div class="chartwrap">${actualChart([cumul(m.rows)],{currency:run.currency})}</div><p class="real-caption">${run.first_day} — ${run.last_day} · Импорт: ${stamp(run.imported_utc)}</p></section><div class="notice real-notice">База хранит агрегаты по дням. Сделки бэктеста, код, параметры и проверки устойчивости не сохранены — здесь показаны только доступные данные.</div>${nextStep('Сравнить с историей исполнения','Выберите соответствующую стратегию, инструмент и счёт вручную.','Выбрать пару для сравнения','real-compare-run:'+encodeURIComponent(run.run_id))}<section class="panel" style="margin-top:20px"><div class="panelhead"><h2>Последние 20 записей дневного PnL</h2></div><div class="table-scroll"><table class="table real-table"><thead><tr><th>ДАТА ОТЧЁТА</th><th>NET PNL · ${esc(run.currency)}</th></tr></thead><tbody>${m.rows.slice(-20).reverse().map(r=>`<tr><td>${r.day}</td><td class="${color(r.value)}">${money(r.value,run.currency)}</td></tr>`).join('')}</tbody></table></div></section></div></div>`}
function comparisonSave(){try{localStorage.setItem('atlas-comparison-v1',JSON.stringify(Object.fromEntries(['compareRun','compareStrategy','compareAccount','compareSymbol','compareStart','compareEnd'].map(k=>[k,rf[k]||'']))))}catch{}}
function comparisonDate(v){return /^\d{4}-\d{2}-\d{2}$/.test(v||'')&&Number.isFinite(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v}
function compareModel(selection=rf){
 const run=remote.backtests.find(r=>r.run_id===selection.compareRun),account=remote.accounts.find(a=>akey(a)===selection.compareAccount);
 if(!run||!account||!selection.compareStrategy||!selection.compareSymbol)return {reason:'Выберите бэктест, стратегию, счёт и инструмент.',code:'selection'};
 if(run.currency!==account.currency)return {reason:'Валюты бэктеста и счёта различаются. Автоматической конвертации нет.',code:'currency'};
 const trades=remote.deals.filter(d=>d.kind==='trade'&&includedDeal(d)&&akey(d)===akey(account)&&d.strategy===selection.compareStrategy&&d.symbol===selection.compareSymbol).slice().sort((a,b)=>a.time_utc.localeCompare(b.time_utc));
 if(!trades.length)return {reason:'У выбранной пары нет торговых записей.',code:'empty'};
 const firstTrade=trades[0].time_utc.slice(0,10),liveEnd=account.latest_snapshot_utc?.slice(0,10);
 if(![run.first_day,run.last_day,liveEnd,firstTrade].every(comparisonDate))return {reason:'Недостаточно корректных дат для общего периода.',code:'dates'};
 const availableStart=[run.first_day,firstTrade].sort().at(-1),availableEnd=[run.last_day,liveEnd].sort()[0];
 if(availableStart>availableEnd)return {reason:`Нет общего периода: бэктест ${run.first_day}–${run.last_day}, история этой стратегии начинается ${firstTrade}.`,code:'overlap'};
 const from=selection.compareStart||'',to=selection.compareEnd||'';
 if(from&&!comparisonDate(from)||to&&!comparisonDate(to)||from&&to&&from>to)return {reason:'Проверьте даты: начало периода должно быть не позже конца.',code:'range'};
 const start=from&&from>availableStart?from:availableStart,end=to&&to<availableEnd?to:availableEnd;
 if(start>end)return {reason:`Выбранные даты вне общего периода ${availableStart} — ${availableEnd}.`,code:'range'};
 const btRows=remote.backtest_days.filter(d=>d.run_id===run.run_id&&d.day>=start&&d.day<=end),liveTrades=trades.filter(d=>d.time_utc.slice(0,10)>=start&&d.time_utc.slice(0,10)<=end);
 const bMap=new Map(daySeries(btRows,d=>d.day,d=>n(d.net_pnl)).map(d=>[d.day,d.value])),lMap=new Map(daySeries(liveTrades,d=>d.time_utc.slice(0,10),net).map(d=>[d.day,d.value]));
 const counts=new Map();for(const d of liveTrades){let k=d.time_utc.slice(0,10);counts.set(k,(counts.get(k)||0)+1)}
 const rows=[];for(let t=Date.parse(start);t<=Date.parse(end);t+=86400000){const day=new Date(t).toISOString().slice(0,10);rows.push({day,bt:bMap.get(day)??0,live:lMap.get(day)??0,btPresent:bMap.has(day),livePresent:lMap.has(day),records:counts.get(day)||0})}
 return {run,account,start,end,availableStart,availableEnd,olderHistory:comparisonDate(account.history_start_day)&&start<account.history_start_day,clipped:!!(from&&from<availableStart||to&&to>availableEnd),bt:sum(btRows,d=>n(d.net_pnl)),live:sum(liveTrades,net),costs:sum(liveTrades,d=>n(d.commission)+n(d.swap)+n(d.fee)),rows,liveTrades,btDays:bMap.size,liveDays:lMap.size,bothDays:rows.filter(d=>d.btPresent&&d.livePresent).length,exits:liveTrades.filter(d=>[1,2,3].includes(d.entry)).length};
}
function comparisonSuggestions(){
 const result=[];
 for(const run of remote.backtests){const name=String(run.strategy).toLowerCase(),id=(name.match(/^s-?0*(\d+)/)||[])[1],instrument=/nas|nq/.test(name)?'Nasdaq':/ger|dax/.test(name)?'DAX':/eur/.test(name)?'EURUSD':'';if(!id||!instrument)continue;
  const family='S-'+id.padStart(3,'0'),scopes=new Map();for(const d of remote.deals){if(d.kind!=='trade'||!includedDeal(d)||AtlasMapping.family(d.strategy)!==id.padStart(3,'0')||AtlasMapping.instrument(d)!==instrument)continue;const k=JSON.stringify([d.strategy,akey(d),d.symbol]);scopes.set(k,{compareRun:run.run_id,compareStrategy:d.strategy,compareAccount:akey(d),compareSymbol:d.symbol,compareStart:'',compareEnd:''})}
  const pairs=[...scopes.values()].map(selection=>({selection,model:compareModel(selection)})).filter(p=>!p.model.reason&&p.model.liveTrades.length&&p.model.btDays).sort((a,b)=>b.model.bothDays-a.model.bothDays||b.model.liveTrades.length-a.model.liveTrades.length||a.selection.compareAccount.localeCompare(b.selection.compareAccount));
  if(pairs.length)result.push({...pairs[0],family,instrument});
 }
 return result;
}
function comparisonDay(day){const m=compareModel();if(m.reason)return;const row=m.rows.find(r=>r.day===day);if(!row)return;const rows=m.liveTrades.filter(d=>d.time_utc.slice(0,10)===day);overlay(`<div class="eyebrow">ИСПОЛНЕНИЕ / ДНЕВНАЯ СВЕРКА</div><h1>${esc(day)}</h1><p class="subtitle">${esc(m.account.login+' · '+rf.compareSymbol)} · UTC</p><div class="cards">${card('Бэктест',row.btPresent?money(row.bt,m.run.currency):'Нет записи','Дата из импортированного отчёта')}${card('Исполнение',row.livePresent?money(row.live,m.run.currency):'Нет записи','Записей MT5: '+rows.length)}</div><p class="help">Каждая строка ниже — исполнение MT5, включая входы и частичные выходы. Сделок бэктеста для попарной сверки нет.</p><div class="searchresults">${rows.map(d=>`<button data-action="real-deal:${encodeURIComponent(dkey(d))}"><strong>#${esc(d.ticket)} · ${esc(d.time_utc.slice(11,19))} · ${money(net(d),m.run.currency)}</strong><small>${['Вход','Выход','Разворот','Close by'][d.entry]||'Запись'} · ${d.volume} lot · ${esc(d.comment||'Без комментария')}</small></button>`).join('')||'<p class="help">В выбранном снимке исполнений за этот день нет.</p>'}</div>`,true);document.querySelector('.drawer')?.setAttribute('aria-label','Дневная сверка '+day)}
function realComparison(){
 const names=[...new Set(remote.deals.filter(d=>d.kind==='trade'&&includedDeal(d)&&!unassigned(d.strategy)).map(d=>d.strategy))].sort();
 const accts=remote.accounts.filter(a=>remote.deals.some(d=>akey(d)===akey(a)&&d.strategy===rf.compareStrategy&&d.kind==='trade'&&includedDeal(d)));
 const syms=[...new Set(remote.deals.filter(d=>d.kind==='trade'&&includedDeal(d)&&d.strategy===rf.compareStrategy&&akey(d)===rf.compareAccount).map(d=>d.symbol))].sort();
 const options=(list,value,first)=>`<option value="">${first}</option>`+list.map(([v,label])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(label)}</option>`).join('');
 const m=compareModel(),suggestions=comparisonSuggestions();
 const pair=`<details class="comparison-picker panel" ${m.reason?'open':''}><summary><div><span class="eyebrow">01 / ПАРА СРАВНЕНИЯ</span><strong>${m.reason?'Выберите источники':esc(m.run.strategy+' ↔ '+rf.compareSymbol+' · '+m.account.login)}</strong></div><span>Изменить пару</span></summary><div class="fields"><div class="field"><label for="rc-run">Импортированный бэктест</label><select id="rc-run" data-compare="compareRun">${options(remote.backtests.map(r=>[r.run_id,r.strategy+' · '+r.file_name]),rf.compareRun,'Выберите бэктест')}</select></div><div class="field"><label for="rc-strategy">Стратегия из сделок</label><select id="rc-strategy" data-compare="compareStrategy">${options(names.map(s=>[s,s]),rf.compareStrategy,'Выберите стратегию')}</select></div><div class="field"><label for="rc-account">Счёт исполнения</label><select id="rc-account" data-compare="compareAccount" ${!rf.compareStrategy?'disabled':''}>${options(accts.map(a=>[akey(a),a.login+' · '+a.server]),rf.compareAccount,'Выберите счёт')}</select></div><div class="field"><label for="rc-symbol">Инструмент исполнения</label><select id="rc-symbol" data-compare="compareSymbol" ${!rf.compareAccount?'disabled':''}>${options(syms.map(s=>[s,s]),rf.compareSymbol,'Выберите инструмент')}</select></div></div><p class="help">Выбор сохраняется только в этом браузере. Соответствие версий и параметров требует отдельной проверки.</p></details>`;
 const suggestionHTML=`<section class="comparison-suggestions"><h2>Пары с пересечением истории</h2><p class="help">Предложения по названию семейства и инструменту. Выбран счёт с наибольшим числом дат с записями в обоих источниках; доходность не участвует в выборе.</p><div class="compare-pairs">${suggestions.map((p,i)=>`<button class="panel" data-action="compare-suggestion:${i}"><span class="badge gray">Версия не сверена</span><strong>${esc(p.family+' · '+p.instrument)}</strong><span>${esc(p.model.account.login+' · '+p.model.account.server)}</span><small>${p.model.start} — ${p.model.end} · ${p.model.liveTrades.length} записей исполнения</small><b>Открыть сравнение →</b></button>`).join('')||'<p class="help">Подходящих предложений нет. Выберите пару вручную.</p>'}</div></section>`;
 const header=heading('ИСПОЛНЕНИЕ / СРАВНЕНИЕ','Бэктест и исполнение','Два источника, один период. Сначала сопоставляем данные, затем изучаем различия.',!m.reason?button('Экспорт дней','compare-export',false,'download'):'');
 if(m.reason)return header+pair+empty(m.code==='selection'?'Начните с пары источников':'Сравнение недоступно',esc(m.reason)+(m.code==='range'?'<div style="margin-top:16px">'+button('Сбросить период','compare-reset-period')+'</div>':''))+suggestionHTML;
 const all=m.rows.slice().reverse(),pages=Math.max(1,Math.ceil(all.length/20));rf.comparePage=Math.min(rf.comparePage||0,pages-1);const shown=all.slice(rf.comparePage*20,rf.comparePage*20+20);
 return header+pair+`<section class="comparison-period panel"><div><span class="eyebrow">02 / ОБЩИЙ ПЕРИОД</span><strong>${m.start} — ${m.end}</strong><small>Доступное пересечение: ${m.availableStart} — ${m.availableEnd}</small></div><div class="comparison-dates"><div class="field"><label for="rc-start">С даты</label><input type="date" id="rc-start" data-compare="compareStart" value="${esc(rf.compareStart||'')}" min="${m.availableStart}" max="${m.availableEnd}"></div><div class="field"><label for="rc-end">По дату</label><input type="date" id="rc-end" data-compare="compareEnd" value="${esc(rf.compareEnd||'')}" min="${m.availableStart}" max="${m.availableEnd}"></div>${button('Всё пересечение','compare-reset-period')}</div></section>${m.clipped?'<div class="notice">Период ограничен доступным пересечением источников.</div>':''}<div class="comparison-caution"><b>Разница сумм ≠ качество исполнения</b><p>Версия, параметры, капитал и риск не сверены. Live — дни UTC; часовой пояс бэктеста неизвестен. Это сравнение денежных результатов, без нормализации объёмов.</p></div>
 <div class="cards comparison-metrics">${card('Бэктест',shortMoney(m.bt,m.run.currency),money(m.bt,m.run.currency))}${card('Исполнение',shortMoney(m.live,m.run.currency),money(m.live,m.run.currency))}${card('Разница · исполнение − тест',shortMoney(m.live-m.bt,m.run.currency),'По суммам сохранённых записей')}${card('Расходы исполнения',shortMoney(m.costs,m.run.currency),'Комиссия + swap + fee · уже в PnL')}</div>
 <section class="panel"><div class="panelhead"><div><h2>Накопленный Net PnL</h2><p>${m.start} — ${m.end} · ${esc(m.run.currency)} · начало отсчёта 0</p></div><div class="legend"><span><i></i>Бэктест</span><span><i style="background:#5a9b83"></i>Исполнение</span></div></div><div class="chartwrap">${actualChart([cumul(m.rows.map(d=>({day:d.day,value:d.bt}))),cumul(m.rows.map(d=>({day:d.day,value:d.live})))],{labels:['Бэктест','Исполнение'],currency:m.run.currency})}</div><p class="real-caption">График суммирует только сохранённые записи: в дни без записей линия сохраняет предыдущую сумму. Это не подтверждение отсутствия сделок и не историческая equity.</p></section>
 <div class="comparison-coverage"><section class="panel"><h2>Что попало в расчёт</h2><div class="real-statline"><span>Календарных дней</span><b>${m.rows.length}</b></div><div class="real-statline"><span>Дней с записью бэктеста / исполнения</span><b>${m.btDays} / ${m.liveDays}</b></div><div class="real-statline"><span>Дат с записью в обоих источниках</span><b>${m.bothDays}</b></div><div class="real-statline"><span>Записей исполнения / выходов</span><b>${m.liveTrades.length} / ${m.exits}</b></div></section><section class="panel"><h2>Источники и границы</h2><p><b>Бэктест:</b> ${esc(m.run.file_name)}</p><p><b>Исполнение:</b> ${esc(rf.compareStrategy)}<br>${esc(m.account.server+' · '+m.account.login+' · '+rf.compareSymbol)}</p>${m.olderHistory?`<p class="comparison-history">В расчёт включены сохранённые сделки до ${m.account.history_start_day} — начала окна последнего снимка счёта. Полнота более ранней истории не подтверждена.</p>`:''}<p>Пропуски сбора не исключены. Открытые позиции не переоцениваются; PnL учитывается по дате исполнения, даже если позиция открыта до выбранного периода. Сделок бэктеста нет, поэтому сверка входов и проскальзывания недоступна.</p></section></div>
 <section class="panel"><div class="panelhead"><div><h2>Дневная сверка</h2><p>«Нет записи» отличается от сохранённого нуля. Разница за день показана только при наличии обеих записей.</p></div></div><div class="table-scroll"><table class="table real-table"><thead><tr><th>ДАТА</th><th>БЭКТЕСТ · ${esc(m.run.currency)}</th><th>ИСПОЛНЕНИЕ</th><th>РАЗНИЦА</th><th>ЗАПИСИ MT5</th></tr></thead><tbody>${shown.map(d=>`<tr><td>${d.day}</td><td>${d.btPresent?money(d.bt,''):'<span class="muted">Нет записи</span>'}</td><td>${d.livePresent?money(d.live,''):'<span class="muted">Нет записи</span>'}</td><td>${d.btPresent&&d.livePresent?money(d.live-d.bt,''):'—'}</td><td>${button(d.records?'Открыть · '+d.records:'Подробнее','compare-day:'+d.day)}</td></tr>`).join('')}</tbody></table></div><div class="real-pagination"><span>Страница ${rf.comparePage+1} / ${pages}</span><div class="row">${rf.comparePage?button('← Ранее в списке','compare-prev'):''}${rf.comparePage+1<pages?button('Более ранние даты →','compare-next'):''}</div></div></section><details class="data-explainer"><summary>Выбрать другую предлагаемую пару</summary>${suggestionHTML}</details>`;
}

function drawReal(){document.body.classList.add('real-mode');const count=remote?groups(remote.deals.filter(d=>d.kind==='trade'&&includedDeal(d))).filter(g=>!unassigned(g.name)).length:0;const navButton=id=>{const label=realNav.find(x=>x[0]===id)?.[1];if(!label)return '';return `<button data-nav="${id}" ${state.page===id?'aria-current="page"':''} class="${state.page===id?'active':''}">${icon(id)}<span>${label}</span>${id==='strategies'?`<span class="count">${count}</span>`:''}</button>`};document.getElementById('mainnav').innerHTML=navButton('overview')+'<div class="navlabel">ИССЛЕДОВАНИЯ</div>'+['strategies','backtests'].map(navButton).join('')+'<div class="navlabel">ИСПОЛНЕНИЕ</div>'+['trades','comparison'].map(navButton).join('')+'<div class="navlabel">ДАННЫЕ</div>'+['accounts','mapping','logs'].map(navButton).join('');document.getElementById('opsnav').innerHTML=button('Новая стратегия · демо','mode-demo',false,'plus');document.querySelector('.sidebar .env').innerHTML='<strong><span class="dot"></span>VPS · Read only</strong>Локальное представление<br>Обновление по кнопке';document.querySelector('.proto').textContent='ЛОКАЛЬНЫЙ ПРОТОТИП';document.getElementById('crumb').textContent=realNav.find(n=>n[0]===state.page)?.[1]||'Данные VPS';let page=state.page==='backtests'&&typeof realBacktests==='function'?realBacktests():state.page==='logs'&&typeof realLogs==='function'?realLogs():remote?({overview:realOverview,strategies:realStrategies,backtests:realBacktests,trades:realTrades,accounts:realAccounts,comparison:realComparison}[state.page]||(()=>empty('Этот этап пока доступен в демо','На VPS нет сохранённых данных для этого экрана. '+button('Посмотреть концепт','mode-demo'))))():empty(remoteError?'Нет соединения с VPS':'Читаю данные VPS…',remoteError?'Проверьте SSH-соединение и нажмите «Обновить с VPS». Демо-данные автоматически не подставляются.':'Счета, сделки и импортированные бэктесты загружаются одним согласованным снимком.');document.getElementById('page').innerHTML=sourceStrip()+page+`<footer class="footer"><span>ATLAS · Локальный прототип / реальные данные VPS</span><span>Торговые данные · только чтение; бэктесты · отдельный расчёт</span></footer>`;ensureModeSelect();if(state.page==='logs'&&typeof ensureLogs==='function')ensureLogs()}
function ensureModeSelect(){let e=document.getElementById('source-mode');if(!e){e=document.createElement('select');e.id='source-mode';e.className='real-toggle';e.setAttribute('aria-label','Источник данных');e.innerHTML='<option value="real">Данные VPS</option><option value="demo">Демо-прототип</option>';document.querySelector('.top-actions').prepend(e)}e.value=dataMode}
const demoRender=render;
render=function(){if(dataMode==='real')return drawReal();document.body.classList.remove('real-mode');demoRender();document.querySelectorAll('[data-nav=trades],[data-nav=accounts],[data-nav=mapping]').forEach(e=>e.remove());document.querySelector('.proto').textContent='DEMO / ПРОТОТИП';document.querySelector('.sidebar .env').innerHTML='<strong><span class="dot"></span>Prototype workspace</strong>Демонстрационные данные<br>Локальная версия';ensureModeSelect()};
async function fetchReal(refresh=false){if(remoteBusy)return;remoteBusy=true;remoteError='';render();try{const res=await fetch('/api/data'+(refresh?'?refresh=1':''),{cache:'no-store'});if(!res.ok)throw new Error('VPS временно недоступен.');const data=await res.json();if(!Array.isArray(data.deals)||!Array.isArray(data.accounts))throw new Error('Неверный формат данных.');remote=data;if(typeof rebuildMappings==='function')rebuildMappings(data);if(!remote.accounts.some(a=>a.currency===rf.currency))rf.currency=remote.accounts[0]?.currency||'USD'}catch(e){remoteError=e.message}finally{remoteBusy=false;render()}}
function setMode(mode){closeOverlay();dataMode=mode;localStorage.setItem('atlas-source',mode);if(mode==='real'){if(!realNav.some(n=>n[0]===state.page))state.page='overview';location.hash=state.page;render();if(!remote)fetchReal()}else{state.page='journey';location.hash='journey';render()}window.scrollTo(0,0)}
const demoAction=action;
action=function(a){if(a==='mode-demo')return setMode('demo');if(a==='real-refresh')return state.page==='logs'?logsAction('logs-refresh'):fetchReal(true);if(dataMode!=='real')return demoAction(a);if(a==='close')return closeOverlay();if(a.startsWith('logs-'))return logsAction(a);if(a.startsWith('compare-'))return comparisonAction(a);if(a.startsWith('searchnav:'))return;if(realNav.some(n=>n[0]===a))return navigate(a);if(a==='real-exclusions')return showExclusions();if(a==='real-exclusions-next'||a==='real-exclusions-prev'){exclusionPage=Math.max(0,exclusionPage+(a.endsWith('next')?1:-1));return showExclusions()}if(a==='real-reset'){rf={...rf,account:'all',strategy:'all',symbol:'all',start:'',end:'',page:0};return render()}if(a==='real-next'||a==='real-prev'){rf.page+=a==='real-next'?1:-1;return render()}if(a.startsWith('real-strategy:')){rf.strategy=decodeURIComponent(a.slice(14));rf.page=0;return navigate('trades')}if(a.startsWith('real-trade-account:')){toggleTradeAccount(decodeURIComponent(a.slice('real-trade-account:'.length)));return render()}if(a.startsWith('real-account:')){rf.account=decodeURIComponent(a.slice(13));rf.strategy='all';rf.symbol='all';rf.page=0;return navigate('trades')}if(a.startsWith('real-deal:'))return realDeal(decodeURIComponent(a.slice(10)));if(a.startsWith('real-run:')){rf.run=decodeURIComponent(a.slice(9));return render()}if(a.startsWith('real-compare-run:')){rf.compareRun=decodeURIComponent(a.slice(17));rf.compareStart='';rf.compareEnd='';rf.comparePage=0;comparisonSave();return navigate('comparison')}if(a==='real-csv'){const csv=v=>{let text=String(v??'');if(/^[=+@\t\r]/.test(text)||/^-[^0-9.]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'};const rows=selectedDeals();const fields=['time_utc','server','login','ticket','strategy','symbol','entry','type','volume','profit','commission','swap','fee','source_strategy','local_mapping_method','local_mapping_anchor'];const content=[fields.join(',')+',net_pnl,currency',...rows.map(d=>fields.map(f=>csv(d[f])).join(',')+','+csv(net(d).toFixed(2))+','+csv(rf.currency))].join('\n');let u=URL.createObjectURL(new Blob(['\ufeff'+content],{type:'text/csv;charset=utf-8'}));let el=document.createElement('a');el.href=u;el.download='atlas-vps-deals.csv';el.click();setTimeout(()=>URL.revokeObjectURL(u),1000);return toast('Экспортированы реальные записи выбранного периода')}return toast('Это действие доступно в демонстрационном режиме')};
document.addEventListener('change',e=>{if(e.target.id==='run-picker'){rf.run=e.target.value;return render()}if(e.target.id==='source-mode')return setMode(e.target.value);const field=e.target.dataset.realFilter;if(field){rf[field]=e.target.value;rf.page=0;if(field==='account'){rf.strategy='all';rf.symbol='all'}render()}const compare=e.target.dataset.compare;if(compare){rf[compare]=e.target.value;if(compare==='compareStrategy'){rf.compareAccount='';rf.compareSymbol=''}if(compare==='compareAccount')rf.compareSymbol='';if(!['compareStart','compareEnd'].includes(compare)){rf.compareStart='';rf.compareEnd=''}rf.comparePage=0;comparisonSave();render()}});
const oldAbout=document.getElementById('about').onclick;document.getElementById('about').onclick=()=>dataMode==='demo'?oldAbout():overlay('<h2>Данные VPS в локальном интерфейсе</h2><p>Чтение PostgreSQL через SSH, в транзакции READ ONLY. Снимок хранится в памяти локального процесса. Обновление — по кнопке.</p><p>Торговые записи, балансы, позиции и дневные результаты бэктестов взяты из VPS. Недоступные параметры и показатели не заменяются демонстрационными.</p>'+button('Закрыть','close',true));
const demoSearch=search;
search=function(){if(dataMode==='demo')return demoSearch();overlay('<h2>Разделы с данными VPS</h2><div class="searchresults">'+realNav.map(([id,label])=>`<button data-action="searchnav:${id}">${label} ↗</button>`).join('')+'</div>')};
if(dataMode==='real')fetchReal();

function comparisonAction(a){
 if(a.startsWith('compare-suggestion:')){const p=comparisonSuggestions()[Number(a.split(':')[1])];if(!p)return;Object.assign(rf,p.selection,{comparePage:0});comparisonSave();render();return window.scrollTo(0,0)}
 if(a==='compare-reset-period'){rf.compareStart='';rf.compareEnd='';rf.comparePage=0;comparisonSave();return render()}
 if(a==='compare-next'||a==='compare-prev'){rf.comparePage=Math.max(0,(rf.comparePage||0)+(a==='compare-next'?1:-1));return render()}
 if(a.startsWith('compare-day:'))return comparisonDay(a.slice(12));
 if(a==='compare-export'){
  const m=compareModel();if(m.reason)return;
  const quote=v=>{let t=String(v??'');if(/^[=+@\t\r]/.test(t)||/^-[^0-9.]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'};
  const fields=['day','backtest_pnl','execution_pnl','difference_if_both_present','backtest_record_present','execution_record_present','execution_records','currency','run_id','strategy','server','login','symbol','period_start','period_end','snapshot_utc','limitations'];
  const text=[fields.join(','),...m.rows.map(d=>[d.day,d.btPresent?d.bt.toFixed(2):'',d.livePresent?d.live.toFixed(2):'',d.btPresent&&d.livePresent?(d.live-d.bt).toFixed(2):'',d.btPresent,d.livePresent,d.records,m.run.currency,m.run.run_id,rf.compareStrategy,m.account.server,m.account.login,rf.compareSymbol,m.start,m.end,remote.fetched_at,'Version parameters capital risk unverified; live UTC; backtest timezone unknown; absence of record is not verified zero'].map(quote).join(','))].join('\n');
  const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='atlas-comparison-'+m.start+'-'+m.end+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return toast('Дневная сверка экспортирована с признаками наличия записей');
 }
}
